atts.custom_css:
selector,selector:hover{color:rgba(0, 0, 0, 0.84) !important;}
selector{text-transform:uppercase !important;font-size:10px !important;font-weight:400 !important;padding:0px 18px 0px 18px !important;}
selector{align-self:flex-start;width:auto;}
:where(selector){background-image:linear-gradient(rgba(255, 255, 255, 0.98), rgba(246, 246, 246, 0.86));line-height:15px;text-align:center;transition:transform 0.45s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.35s, box-shadow 0.35s;}
